package dev.celerbi.easyfarmersdelightcompat.integration.jei;
import dev.celerbi.easyfarmersdelightcompat.integration.FarmerHarvestInfo;
import dev.celerbi.easyfarmersdelightcompat.registry.ModBlocks;
import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.IFocusGroup;import mezz.jei.api.recipe.RecipeIngredientRole;import mezz.jei.api.recipe.RecipeType;import mezz.jei.api.recipe.category.IRecipeCategory;
import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.world.item.ItemStack;
public final class FarmerHarvestJeiCategory implements IRecipeCategory<FarmerHarvestInfo>{private final IDrawable icon;public FarmerHarvestJeiCategory(IGuiHelper g){icon=g.createDrawableItemStack(new ItemStack(ModBlocks.RICH_FARMER_ITEM.get()));}public RecipeType<FarmerHarvestInfo> getRecipeType(){return EasyFdJeiPlugin.FARMER_HARVEST;}public Component getTitle(){return Component.translatable("jei.easyfarmersdelightcompat.farmer_harvest");}public IDrawable getIcon(){return icon;}public int getWidth(){return 180;}public int getHeight(){return 82;}public void setRecipe(IRecipeLayoutBuilder b,FarmerHarvestInfo r,IFocusGroup f){b.addInputSlot(8,8).addItemStack(r.input());b.addSlot(RecipeIngredientRole.CATALYST,48,8).addIngredients(r.tool());for(int i=0;i<Math.min(4,r.outputs().size());i++)b.addOutputSlot(104+i*18,8).addItemStack(r.outputs().get(i));}public void draw(FarmerHarvestInfo r,IRecipeSlotsView v,GuiGraphics g,double mx,double my){var font=Minecraft.getInstance().font;g.drawString(font,"+",35,13,0x404040,false);g.drawString(font,"→",82,13,0x404040,false);int y=36;for(var line:font.split(r.description(),150)){g.drawString(font,line,4,y,0x555555,false);if((y+=9)>78)break;}}}
